@prefix ns1: <https://example.org/shacl-study/source-semantics/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

ns1:review a ns1:Review ;
    ns1:classification "required"^^xsd:string ;
    ns1:dependencyCount 0 ;
    ns1:hasDependencyEntry false ;
    ns1:scopeDefault "required"^^xsd:string ;
    ns1:task "consumer_scope"^^xsd:string .

shapes_turtle:
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .

owl:Class rdfs:subClassOf rdfs:Class .

owl:DatatypeProperty rdfs:subClassOf rdf:Property .

<https://example.org/shacl-study/source-semantics/PolicyShape> a sh:NodeShape ;
    sh:sparql [ sh:message "dependency_entry_policy" ;
            sh:select """PREFIX ex: <https://example.org/shacl-study/source-semantics/>
SELECT $this WHERE {
      $this ex:task ?task; ex:classification ?actual;
        ex:hasDependencyEntry ?present; ex:dependencyCount ?count.
      FILTER(STR(?task) = "dependency_knowledge")
      BIND(IF(!?present,"unknown",IF(?count = 0,"explicit_empty","reported_nonempty")) AS ?expected)
      FILTER(STR(?actual) != STR(?expected))
    }""" ],
        [ sh:message "consumer_scope_policy" ;
            sh:select """PREFIX ex: <https://example.org/shacl-study/source-semantics/>
SELECT $this WHERE {
      $this ex:task ?task; ex:classification ?actual; ex:scopeDefault ?fallback.
      FILTER(STR(?task) = "consumer_scope")
      OPTIONAL { $this ex:declaredScope ?declared }
      BIND(COALESCE(?declared,?fallback) AS ?expected)
      FILTER(STR(?actual) != STR(?expected))
    }""" ] ;
    sh:targetClass <https://example.org/shacl-study/source-semantics/Review> .

